 const defaultFormatter = value => isArray(value)
   ? value.map(v => String(v))
@@ -25,10 +26,16 @@ export function tickCount(scale, count, minStep) {
       count = Math.max(count, scale.bins.length);
     }
     if (minStep != null) {
-      count = Math.min(
